-- Read-only: run before applying Week 8; compare against existing applied history.
select version,name from supabase_migrations.schema_migrations order by version;
select table_name,column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema='public' and table_name in ('profiles','caption_lab_admins','caption_lab_chains','caption_lab_steps','caption_lab_models','caption_lab_providers','caption_lab_mix','caption_lab_images','caption_lab_requests','caption_lab_responses') order by table_name,ordinal_position;
select c.relname,p.polname,p.polcmd,pg_get_expr(p.polqual,p.polrelid) as using_clause,pg_get_expr(p.polwithcheck,p.polrelid) as check_clause from pg_policy p join pg_class c on c.oid=p.polrelid where c.relname in ('profiles','caption_lab_admins','caption_lab_images');
select grantee,table_name,privilege_type from information_schema.table_privileges where table_schema='public' and table_name in ('profiles','caption_lab_admins','caption_lab_chains','caption_lab_steps') order by table_name,grantee,privilege_type;
select grantee,table_name,column_name,privilege_type from information_schema.column_privileges where table_schema='public' and table_name='profiles' order by grantee,column_name,privilege_type;
select n.nspname,p.proname,p.oid::regprocedure,p.prosecdef,p.proacl,pg_get_functiondef(p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prokind='f' and (p.prosrc ilike '%profiles%' or p.proname ilike '%profile%');
select conrelid::regclass,conname,pg_get_constraintdef(oid) from pg_constraint where conrelid in ('public.profiles'::regclass,'public.caption_lab_steps'::regclass,'public.caption_lab_chains'::regclass,'public.caption_lab_requests'::regclass,'public.caption_lab_responses'::regclass);
